import{$,api,escapeHtml,fillFilters,queryString,renderMarkdown,showError,wirePager}from"./common.js";let currentPage=1,lastPages=1;let saved={};try{saved=JSON.parse(localStorage.getItem("interview-open-source-progress")||"{}")||{}}catch{}function persist(){localStorage.setItem("interview-open-source-progress",JSON.stringify(saved))}function cards(items){return items.map((item)=>{const state=saved[item.id]||"";return`<article class="card" data-id="${item.id}"><div class="meta">${escapeHtml(item.repository)} · ${escapeHtml(item.module)}</div><h2>${escapeHtml(item.question)}</h2><div class="source-line">${escapeHtml(item.relative_path)}</div><details class="answer"><summary>${item.answer.trim()?"展开开源答案":"来源未提供答案"}</summary><div class="markdown">${item.answer.trim()?renderMarkdown(item.answer):'<p class="muted">该来源只列出了问题，没有提供对应答案。</p>'}</div><div class="actions"><button class="btn state ${state==="mastered"?"active":""}" data-state="mastered">已掌握</button><button class="btn state ${state==="vague"?"active":""}" data-state="vague">模糊</button><button class="btn state ${state==="unknown"?"active":""}" data-state="unknown">不会</button><a class="btn" target="_blank" rel="noopener" href="${item.repository_url}/blob/HEAD/${encodeURI(item.relative_path)}">原文件 ↗</a></div></details></article>`}).join("")}function wireStates(){$("#list").querySelectorAll("[data-state]").forEach((button)=>button.onclick=()=>{saved[button.closest(".card").dataset.id]=button.dataset.state;persist();load(currentPage)})}async function load(page=1){currentPage=page;try{const answered=$("#answered").checked?"&answered=1":"";const data=await api(`/api/questions?${queryString(page,15)}${answered}`);lastPages=data.pages;$("#result").textContent=`共 ${data.total.toLocaleString()} 道问题`;$("#list").innerHTML=data.items.length?cards(data.items):'<div class="empty">没有符合条件的问题</div>';wireStates();wirePager({page:data.page,pages:data.pages,onChange:load})}catch(error){showError(error)}}await fillFilters();for(const id of["q","module","source","answered"]){$("#"+id).addEventListener(id==="q"?"input":"change",()=>load(1))}$("#random").onclick=()=>load(Math.max(1,Math.floor(Math.random()*Math.max(1,lastPages))+1));await load();
